package com.smarthub.plus;
import android.content.*;import android.os.*;import android.widget.*;import java.util.concurrent.*;
/** Real per-channel Internet-audio binding. No factory tokens or catalogue credentials are copied. */
public final class IPAudioActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private ReceiverCatalog.Channel channel;private EditText url,delay,volume;private CheckBox enabled;private TextView status;private final Handler main=new Handler(Looper.getMainLooper());private boolean closed;
 private final Runnable tick=new Runnable(){public void run(){if(closed)return;String s=prefs().getString("ip_audio_status","");status.setText(s.equals("IP_AUDIO_PLAYING")?tx("الصوت الشبكي يعمل","Internet audio playing"):s.equals("IP_AUDIO_FAILED")?tx("تعذر المصدر؛ عاد صوت القناة الأصلي","Source failed; original channel audio restored"):s.isEmpty()?tx("صوت القناة الأصلي","Original channel audio"):tx("جارٍ الاتصال أو تجهيز الصوت…","Connecting or buffering audio…"));main.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=page(tx("صوت عبر الإنترنت للقناة","Channel Internet Audio"));TextView name=text("",22,true);body.addView(name);url=field(body,tx("رابط مصدر صوت HTTP / HTTPS","HTTP / HTTPS audio source URL"),"");url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);delay=field(body,tx("تأخير إضافي للصوت بالميلي ثانية · 0–30000","Additional audio delay in ms · 0–30000"),"0");delay.setInputType(2);volume=field(body,tx("مستوى الصوت · 0–100","Audio volume · 0–100"),"80");volume.setInputType(2);enabled=check(body,tx("تشغيل المصدر تلقائياً لهذه القناة","Automatically use this source for this channel"),false);note(body,tx("يبدأ مصدر الصوت من الإنترنت داخل المشغل، ويُكتم صوت DVB عند جاهزيته. التوقيت يدوي لأن مصدر الإنترنت والبث قد يملكان تأخيراً مختلفاً.","The player loads Internet audio and mutes DVB when it is ready. Timing is manual because Internet and broadcast sources can have different latency."));action(body,tx("حفظ وتطبيق","Save and apply"),()->{if(channel==null)return;try{IPAudioBinding binding=new IPAudioBinding(url.getText().toString().trim(),Integer.parseInt(delay.getText().toString()),Integer.parseInt(volume.getText().toString()),enabled.isChecked());ReceiverCatalog.Channel target=channel;io.execute(()->{try{binding.save(this,target.physical());runOnUiThread(()->{if(!closed){startActivity(new Intent(this,DvbPlaybackActivity.class).putExtra("channel",target.id));finish();}});}catch(Exception error){runOnUiThread(()->toast(tx("تعذر الحفظ الآمن","Secure save failed")));}});}catch(Exception bad){toast(tx("تحقق من الرابط والتأخير ومستوى الصوت","Check the URL, delay and volume"));}});action(body,tx("حذف الارتباط والعودة للصوت الأصلي","Remove binding and restore channel audio"),()->{if(channel==null)return;ReceiverCatalog.Channel target=channel;io.execute(()->{try{IPAudioBinding.remove(this,target.physical());runOnUiThread(()->{if(!closed){startActivity(new Intent(this,DvbPlaybackActivity.class).putExtra("channel",target.id));finish();}});}catch(Exception e){runOnUiThread(()->toast(tx("تعذر حذف الارتباط","Could not remove binding")));}});});status=text("",15,true);body.addView(status);io.execute(()->{ReceiverCatalog.Channel c=ReceiverCatalog.get(this).channel(prefs().getLong("own_dvb_channel",-1));IPAudioBinding b=c==null?null:IPAudioBinding.read(this,c.physical());runOnUiThread(()->{if(closed)return;channel=c;name.setText(c==null?tx("شغّل قناة في IRAQhub أولاً","Play a channel in IRAQhub first"):c.name);if(b!=null){url.setText(b.url);delay.setText(Integer.toString(b.delay));volume.setText(Integer.toString(b.volume));enabled.setChecked(b.enabled);}});});main.post(tick);}
 @Override protected void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
